const getBrands = `-- name: GetBrands :many
SELECT b.id, b.name, b.logo_url, b.category_id, b.created_at, b.updated_at, c.name as category_name 
FROM brands b
LEFT JOIN categories c ON b.category_id = c.id
ORDER BY b.name ASC
`

type GetBrandsRow struct {
	ID           string         `json:"id"`
	Name         string         `json:"name"`
	LogoUrl      sql.NullString `json:"logo_url"`
	CategoryID   sql.NullString `json:"category_id"`
	CreatedAt    sql.NullTime   `json:"created_at"`
	UpdatedAt    sql.NullTime   `json:"updated_at"`
	CategoryName sql.NullString `json:"category_name"`
}

// Brands
func (q *Queries) GetBrands(ctx context.Context) ([]GetBrandsRow, error) {
	rows, err := q.db.QueryContext(ctx, getBrands)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetBrandsRow
	for rows.Next() {
		var i GetBrandsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.LogoUrl,
			&i.CategoryID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CategoryName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

