const listProperties = `-- name: ListProperties :many
SELECT p.id, p.business_id, p.title, p.description, p.address_id, p.price_per_night, p.currency, p.number_of_guests, p.number_of_bedrooms, p.type, p.image_urls, p.created_at, p.updated_at, b.name as business_name, a.city, a.address_line1
FROM properties p
JOIN businesses b ON p.business_id = b.id
LEFT JOIN addresses a ON p.address_id = a.id
WHERE ($1::text IS NULL OR a.city ILIKE '%' || $1 || '%')
AND ($2::numeric IS NULL OR p.price_per_night <= $2)
AND ($3::int IS NULL OR p.number_of_bedrooms >= $3)
`

type ListPropertiesParams struct {
	City     sql.NullString `json:"city"`
	MaxPrice sql.NullString `json:"max_price"`
	MinRooms sql.NullInt32  `json:"min_rooms"`
}

type ListPropertiesRow struct {
	ID               string           `json:"id"`
	BusinessID       string           `json:"business_id"`
	Title            string           `json:"title"`
	Description      sql.NullString   `json:"description"`
	AddressID        sql.NullString   `json:"address_id"`
	PricePerNight    string           `json:"price_per_night"`
	Currency         string           `json:"currency"`
	NumberOfGuests   sql.NullInt32    `json:"number_of_guests"`
	NumberOfBedrooms sql.NullInt32    `json:"number_of_bedrooms"`
	Type             PropertyTypeEnum `json:"type"`
	ImageUrls        []string         `json:"image_urls"`
	CreatedAt        sql.NullTime     `json:"created_at"`
	UpdatedAt        sql.NullTime     `json:"updated_at"`
	BusinessName     string           `json:"business_name"`
	City             sql.NullString   `json:"city"`
	AddressLine1     sql.NullString   `json:"address_line1"`
}

// Property
func (q *Queries) ListProperties(ctx context.Context, arg ListPropertiesParams) ([]ListPropertiesRow, error) {
	rows, err := q.db.QueryContext(ctx, listProperties, arg.City, arg.MaxPrice, arg.MinRooms)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPropertiesRow
	for rows.Next() {
		var i ListPropertiesRow
		if err := rows.Scan(
			&i.ID,
			&i.BusinessID,
			&i.Title,
			&i.Description,
			&i.AddressID,
			&i.PricePerNight,
			&i.Currency,
			&i.NumberOfGuests,
			&i.NumberOfBedrooms,
			&i.Type,
			pq.Array(&i.ImageUrls),
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.BusinessName,
			&i.City,
			&i.AddressLine1,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

